-- Supplier receiving, table-close photos, cancellation approvals, customer-only resets and push subscriptions.
CREATE TABLE IF NOT EXISTS `suppliers` (`id` INT AUTO_INCREMENT PRIMARY KEY,`name` VARCHAR(150) NOT NULL,`contact_name` VARCHAR(120) DEFAULT NULL,`phone_number` VARCHAR(30) DEFAULT NULL,`email` VARCHAR(120) DEFAULT NULL,`address` TEXT DEFAULT NULL,`notes` TEXT DEFAULT NULL,`created_at` DATETIME NOT NULL,`updated_at` DATETIME NOT NULL,INDEX `idx_suppliers_name` (`name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `supply_receipts` (`id` INT AUTO_INCREMENT PRIMARY KEY,`supplier_id` INT NOT NULL,`reference_number` VARCHAR(100) DEFAULT NULL,`received_by_user_id` INT NOT NULL,`receipt_file_path` VARCHAR(500) DEFAULT NULL,`notes` TEXT DEFAULT NULL,`received_at` DATETIME NOT NULL,`created_at` DATETIME NOT NULL,INDEX `idx_supply_supplier_received` (`supplier_id`,`received_at`),CONSTRAINT `fk_supply_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_supply_receiver` FOREIGN KEY (`received_by_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `supply_receipt_items` (`id` INT AUTO_INCREMENT PRIMARY KEY,`supply_receipt_id` INT NOT NULL,`inventory_item_id` INT NOT NULL,`quantity` DECIMAL(9,2) NOT NULL,`unit_cost` DECIMAL(9,2) DEFAULT NULL,INDEX `idx_supply_receipt_item` (`supply_receipt_id`),CONSTRAINT `fk_supply_item_receipt` FOREIGN KEY (`supply_receipt_id`) REFERENCES `supply_receipts`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_supply_item_inventory` FOREIGN KEY (`inventory_item_id`) REFERENCES `inventory_items`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `table_close_evidence` (`id` INT AUTO_INCREMENT PRIMARY KEY,`table_id` INT NOT NULL,`order_id` INT NOT NULL,`waiter_id` INT NOT NULL,`image_path` VARCHAR(500) NOT NULL,`created_at` DATETIME NOT NULL,INDEX `idx_tce_table_created` (`table_id`,`created_at`),CONSTRAINT `fk_tce_table` FOREIGN KEY (`table_id`) REFERENCES `restaurant_tables`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_tce_order` FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_tce_waiter` FOREIGN KEY (`waiter_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `order_cancellation_requests` (`id` INT AUTO_INCREMENT PRIMARY KEY,`order_id` INT NOT NULL,`requested_by_user_id` INT NOT NULL,`reason` TEXT NOT NULL,`status` ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',`reviewed_by_user_id` INT DEFAULT NULL,`review_notes` TEXT DEFAULT NULL,`created_at` DATETIME NOT NULL,`reviewed_at` DATETIME DEFAULT NULL,UNIQUE KEY `uq_cancel_request_order_pending` (`order_id`,`status`),CONSTRAINT `fk_ocr_order` FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_ocr_requester` FOREIGN KEY (`requested_by_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_ocr_reviewer` FOREIGN KEY (`reviewed_by_user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `password_reset_codes` (`id` INT AUTO_INCREMENT PRIMARY KEY,`user_id` INT NOT NULL,`code_hash` VARCHAR(255) NOT NULL,`expires_at` DATETIME NOT NULL,`consumed_at` DATETIME DEFAULT NULL,`created_at` DATETIME NOT NULL,INDEX `idx_prc_user_expires` (`user_id`,`expires_at`),CONSTRAINT `fk_prc_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `push_subscriptions` (`id` INT AUTO_INCREMENT PRIMARY KEY,`user_id` INT NOT NULL,`platform` ENUM('web','android','ios') NOT NULL,`token` VARCHAR(512) NOT NULL,`created_at` DATETIME NOT NULL,`updated_at` DATETIME NOT NULL,UNIQUE KEY `uq_push_subscription_token` (`token`),INDEX `idx_push_user_platform` (`user_id`,`platform`),CONSTRAINT `fk_push_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
